-- 上外(sufe)必修一 情景闯关题(context_questions, grade=11, volume='elective1', publisher='sufe')。Aaron 跑。幂等(只删 sufe 本册)。
BEGIN;
DELETE FROM public.context_questions WHERE publisher='sufe' AND volume='elective1';

COMMIT;
SELECT unit, count(*) FROM public.context_questions WHERE publisher='sufe' AND volume='elective1' GROUP BY unit ORDER BY unit;
SELECT count(*) AS context_q_sufe_elective1 FROM public.context_questions WHERE publisher='sufe' AND volume='elective1';
